pub fn on_fetched_data_available(&self, data: impl AsRef<[u8]>) -> Result<(), ProtocolError> {
    let data = data.as_ref();
    if data.len() > i32::MAX as usize {
        return Err(ProtocolError::Size(data.len()));
    }
